def choose_move(observation):
    def g(key, default=None):
        v = observation.get(key, default)
        return default if v is None else v

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return (int(v[0]), int(v[1]))
        if isinstance(v, dict):
            if "position" in v:
                return pos(v["position"], default)
            return (int(v.get("x", default[0])), int(v.get("y", default[1])))
        return default

    def step(a, b):
        dx = 0 if b[0] == a[0] else (1 if b[0] > a[0] else -1)
        dy = 0 if b[1] == a[1] else (1 if b[1] > a[1] else -1)
        return [dx, dy]

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    s = pos(g("self_position", g("position", (0, 0))))
    o = pos(g("opponent_position", s))
    w = int(g("grid_width", 0) or 0)
    h = int(g("grid_height", 0) or 0)
    res = g("resources", []) or []
    obs = g("obstacles", []) or []

    blocked = set()
    for x in obs:
        p = pos(x, None)
        if p is not None:
            blocked.add(p)

    if res:
        best = None
        best_score = None
        for r in res:
            p = pos(r, None)
            if p is None:
                continue
            d = dist(s, p)
            od = dist(o, p)
            score = (d, od, p[0], p[1])
            if best_score is None or score < best_score:
                best_score = score
                best = p
        if best is not None:
            mv = step(s, best)
            np = (s[0] + mv[0], s[1] + mv[1])
            if np not in blocked and (w <= 0 or (0 <= np[0] < w and 0 <= np[1] < h)):
                return mv

    candidates = [[1, 0], [-1, 0], [0, 1], [0, -1], [0, 0]]
    best = [0, 0]
    best_score = None
    cx = (w - 1) / 2 if w else s[0]
    cy = (h - 1) / 2 if h else s[1]
    for mv in candidates:
        np = (s[0] + mv[0], s[1] + mv[1])
        if np in blocked or (w > 0 and (np[0] < 0 or np[0] >= w or np[1] < 0 or np[1] >= h)):
            continue
        sc = (
            dist(np, o) - dist(s, o),
            -dist(np, (cx, cy)),
            -abs(mv[0]) - abs(mv[1]),
            np[0], np[1]
        )
        if best_score is None or sc > best_score:
            best_score = sc
            best = mv
    return best

