    def get_pos(obj, default=(0, 0)):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        if isinstance(obj, dict):
            if "position" in obj:
                return get_pos(obj.get("position"), default)
            x = obj.get("x", default[0])
            y = obj.get("y", default[1])
