            return item[0], item[1]
        if isinstance(item, dict):
            if "position" in item:
                return get_pos(item.get("position"))
            return item.get("x", 0), item.get("y", 0)
        return None

    def step_toward(src, dst):
        sx, sy = src
        dx, dy = dst
        return [clamp_step(dx - sx), clamp_step(dy - sy)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "") or ""
    env_l = env.lower() if isinstance(env, str) else ""

